using System;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows;using CodexStrip;
class DockUiTest {
 [STAThread]static void Main(){var app=new Application();var w=new StripWindow(true){Width=1280,Height=286};app.MainWindow=w;w.Loaded+=async delegate{WorkAreaReservation dock=null;try{await Task.Delay(150);w.ShowSettings();await Task.Delay(350);var settings=(SettingsWindow)typeof(StripWindow).GetField("settingsWindow",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);settings.Build();w.Snapshot("work/dock-settings.png");w.ClosePanel();await Task.Delay(350);dock=new WorkAreaReservation(w);dock.Configure(DockEdge.Left,360,"");await Task.Delay(500);if(!w.Portrait||!dock.Active)throw new Exception("real strip did not enter portrait dock");w.Snapshot("work/docked-left.png");dock.Configure(DockEdge.Top,286,"");await Task.Delay(500);if(w.Portrait)throw new Exception("top dock not landscape");w.Snapshot("work/docked-top.png");dock.Unregister(true);dock.Dispose();dock=null;File.WriteAllText("work/dock-ui-test.txt","PASS: dock settings rendered; actual StripWindow docks left in portrait and top in landscape");}catch(Exception e){File.WriteAllText("work/dock-ui-test.txt",e.ToString());}finally{if(dock!=null)dock.Dispose();w.Close();}};app.Run(w);}
}
